import { test, expect } from '@playwright/test';

test.describe('Order Confirmation After Successful Payment', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display order confirmation after successful payment', async ({ page }) => {
    // Verify checkout page is visible
    const checkoutPage = page.getByRole('main');
    await expect(checkoutPage).toBeVisible();

    // Fill in shipping details
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const addressInput = page.getByLabel('Shipping Address');
    await addressInput.fill('123 Main St');

    // Fill in payment details
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('4111 1111 1111 1234');

    const expiryInput = page.getByLabel('Expiry Date');
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click pay button
    const payButton = page.getByRole('button', { name: /pay/i });
    await payButton.click();

    // Wait for payment processing
    await page.waitForResponse(response => 
      response.url().includes('/api/payment/process') && response.status() === 200
    );

    // Verify order confirmation page is displayed
    const confirmationPage = page.getByRole('main');
    await expect(confirmationPage).toBeVisible();

    // Verify success message
    const successMessage = page.getByText(/order confirmed/i);
    await expect(successMessage).toBeVisible();

    // Verify order number is displayed
    const orderNumber = page.getByText(/\d{8,}/);
    await expect(orderNumber).toBeVisible();

    // Verify confirmation details
    const orderDetails = page.getByText(/order details/i);
    await expect(orderDetails).toBeVisible();

    // Verify total amount is displayed
    const totalAmount = page.getByText(/\$\d+\.\d{2}/);
    await expect(totalAmount).toBeVisible();
  });

  test('should handle payment failure and display error message', async ({ page }) => {
    // Fill in shipping details
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const addressInput = page.getByLabel('Shipping Address');
    await addressInput.fill('404 Test Ln');

    // Fill in invalid payment details
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('1111 1111 1111 111');

    const expiryInput = page.getByLabel('Expiry Date');
    await expiryInput.fill('01/20');

    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click pay button
    const payButton = page.getByRole('button', { name: /pay/i });
    await payButton.click();

    // Wait for payment processing response
    await page.waitForResponse(response => 
      response.url().includes('/api/payment/process') && response.status() === 402
    );

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details
    const errorDetails = page.getByText(/invalid card details/i);
    await expect(errorDetails).toBeVisible();

    // Verify user is still on checkout page
    const checkoutPage = page.getByRole('main');
    await expect(checkoutPage).toBeVisible();

    // Verify pay button is still enabled
    const payButtonState = await payButton.evaluate(el => el.disabled);
    expect(payButtonState).toBe(false);
  });
});
